package com.bank.messaging.demo;

import java.util.logging.*;

public class MessagingDemo {
    private static final Logger log = Logger.getLogger(MessagingDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        MessagingAdvisor advisor = new MessagingAdvisor();
        KafkaEventPublisher kafka = new KafkaEventPublisher();
        SqsJobDispatcher sqs = new SqsJobDispatcher();
        RabbitRouter rabbit = new RabbitRouter();

        // Scenario 1 — something happened: trade event read by many teams
        MessagingDecision d1 = advisor.recommend("trade-settled-event", true, false);
        log.info(() -> "Scenario 1 -> " + d1.getTechnology() + " : " + d1.getReason());
        kafka.publish("trade.settled", "SAV2001",
                "{\"from\":\"SAV2001\",\"to\":\"CUR3001\",\"amount\":50000}");

        // Scenario 2 — a job needs doing: one worker generates one PDF
        MessagingDecision d2 = advisor.recommend("monthly-statement-job", false, false);
        log.info(() -> "Scenario 2 -> " + d2.getTechnology() + " : " + d2.getReason());
        sqs.dispatch("statement-jobs", "{\"account\":\"SAV2001\",\"month\":\"OCT\"}");

        // Scenario 3 — route this message: regional loan routing
        MessagingDecision d3 = advisor.recommend("loan-routing", false, true);
        log.info(() -> "Scenario 3 -> " + d3.getTechnology() + " : " + d3.getReason());
        rabbit.route("loan.exchange", "loan.approval.mumbai",
                "{\"applicant\":\"Rajesh\",\"amount\":2000000}");
    }
}

// ─── Would be in MessagingDecision.java in a real project ───
class MessagingDecision {
    private final String technology;
    private final String reason;
    MessagingDecision(String technology, String reason) {
        this.technology = technology; this.reason = reason;
    }
    String getTechnology() { return technology; }
    String getReason() { return reason; }
}

// ─── Would be in MessagingAdvisor.java in a real project ───
class MessagingAdvisor {
    private static final Logger log = Logger.getLogger(MessagingAdvisor.class.getName());

    // manyReaders = multiple independent consumers need the same data (+replay)
    // complexRouting = message must be routed to specific destinations by key
    MessagingDecision recommend(String useCase, boolean manyReaders, boolean complexRouting) {
        log.fine(() -> "Evaluating use case: " + useCase);
        if (manyReaders) {
            return new MessagingDecision("Kafka",
                "something happened: durable event log, many independent consumers, replay");
        }
        if (complexRouting) {
            return new MessagingDecision("RabbitMQ",
                "route this message: exchanges, routing keys and bindings");
        }
        return new MessagingDecision("AWS SQS",
            "a job needs doing: simple managed queue, one worker per message");
    }
}

